const alreadyProcessed = RM.getVariable('country_score_applied');
const country = (RM.getInput('raq_e3w6utzc') || '').toLowerCase().trim();

if (!country) {
  console.log('No country input yet, skipping.');
} else if (alreadyProcessed === 'true' && RM.getVariable('country_score_country') === country) {
  console.log('Country score already applied for this country, skipping re-execution.');
} else {
  // Define target country keywords
  const targetCountries = ['canada', 'united states', 'usa', 'america', 'united kingdom', 'uk', 'england', 'australia', 'new zealand', 'ireland', 'netherlands', 'sweden', 'denmark', 'norway', 'finland', 'germany', 'switzerland', 'singapore', 'austria', 'belgium', 'luxembourg', 'portugal', 'united arab emirates', 'japan'];

  // Define avoided country keywords
  const avoidedCountries = ['india', 'pakistan', 'bangladesh', 'nigeria', 'ethiopia', 'kenya', 'sri lanka', 'cambodia', 'myanmar', 'nepal', 'yemen', 'afghanistan', 'sudan', 'congo (democratic republic)', 'tanzania', 'uganda', 'laos', 'haiti', 'madagascar', 'mozambique'];

  // Check matches
  const isTargetCountry = targetCountries.some(function(keyword) {
    return country.indexOf(keyword) !== -1;
  });

  const isAvoidedCountry = avoidedCountries.some(function(keyword) {
    return country.indexOf(keyword) !== -1;
  });

  // Determine result
  var result;
  if (isAvoidedCountry) {
    result = 'avoided';
  } else if (isTargetCountry) {
    result = 'yes';
  } else {
    result = 'no';
  }

  // Check previous result to reverse any prior score adjustment
  const previousResult = RM.getVariable('is_target_country');

  if (previousResult === 'avoided') {
    RM.adjustScore('quest_app_lead_score', 1);
  } else if (previousResult === 'yes') {
    RM.adjustScore('quest_app_lead_score', -1);
  }

  // Set variable and custom field with updated values
  RM.setVariable('is_target_country', result);
  RM.setCustomField('quest_app_target_country', result);

  // Apply new score adjustment
  if (isAvoidedCountry) {
    RM.adjustScore('quest_app_lead_score', -1);
  } else if (isTargetCountry) {
    RM.adjustScore('quest_app_lead_score', 1);
  }

  // Store the country value that was processed so we can detect re-runs with the same value
  RM.setVariable('country_score_country', country);

  // Mark as processed
  RM.setVariable('country_score_applied', 'true');

  console.log('Country:', country, '| Previous Result:', previousResult, '| New Result:', result, '| Score:', RM.getScore('quest_app_lead_score'));
}
